/* Ember's chat: a launcher's reading pane. The prompt is a soft borderless block one step off the
   page with large 16 px corners, tool results and cards sit on a faint fill with no ring to speak
   of, secondary text is the launcher's quiet gray, and links take the coral red a step toward the
   text so they read on either page.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Ember and Ember
   Light and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 16px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 5%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 6%, transparent);
  --cv-text: var(--agent-text);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 70%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 64%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));

  /* Pending cmux#46490 (--cv-user-bubble-text): the launcher draws your own prompt in its gray, a
     step under the reply's white, so the answer reads first. Inert until it lands. */
  --cv-user-bubble-text: color-mix(in srgb, var(--agent-text) 72%, transparent);

  /* Pending cmux#46846 (--menu-*): the action panel (the menu a launcher opens on its shortcut)
     and every context menu. Inert until it lands.
     A floating panel one step up from the page with 12 px corners and a 6 px inset, 34 px rows, a
     neutral gray highlight (the selected row's gray, never colored) with an 8 px corner, the
     shortcut hints in gray at the right, small semibold gray section labels, separators edge to
     edge between sections, destructive rows in the coral red a step toward the text, and
     submenus 4 px off their row with their first row level with it. */
  --menu-radius: 12px;
  --menu-padding: 6px;
  --menu-fill: color-mix(in srgb, var(--agent-text) 7%, var(--agent-page-bg));
  --menu-border: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-row-height: 34px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-hover-radius: 8px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --menu-separator-inset: 0px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-label-weight: 600;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-destructive: color-mix(in srgb, var(--agent-accent) 66%, var(--agent-text));
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: 4px;
  --menu-submenu-align-offset: -6px;
}

